H, W = map(int, input().split())
grid = [list(map(int, list(input()))) for _ in range(H)]
R, C = map(int, input().split())

from collections import deque

queue = deque()
overloaded = set()

# Initial signal
queue.append((R, C))

while queue:
    r, c = queue.popleft()
    if (r, c) in overloaded:
        continue

    grid[r][c] += 1

    if grid[r][c] > 9:
        grid[r][c] = 0
        overloaded.add((r, c))

        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W:
                    queue.append((nr, nc))

for row in grid:
    print("".join(map(str, row)))
